    html: { about: 'HTML ist die Auszeichnungssprache des Webs: Text in Tags verpackt, aus denen ein Browser Überschriften, Absätze, Links und Bilder macht.', note: 'HTML lässt sich in jedem Browser öffnen und direkt in eine Website oder ein CMS einfügen.' },
    rtf: { about: 'RTF ist ein offenes, textbasiertes Dokumentformat, das einfache Formatierungen — fett, kursiv, Schriften, Tabellen — mitführt, ohne Sie an ein einziges Textprogramm zu binden.', note: 'RTF öffnet sich in Word, Pages, LibreOffice, WordPad und praktisch jedem jemals geschriebenen Textprogramm.' },
    odt: { about: 'ODT ist das OpenDocument-Textformat von LibreOffice und OpenOffice — ein ISO-Standard statt eines Herstellerformats.', note: 'ODT ist das native, vollständig bearbeitbare Format für LibreOffice und OpenOffice.' },
    epub: { about: 'EPUB ist ein Format mit fließendem Text: Es hat keine feste Seitengröße, sondern bricht den Text auf die jeweilige Bildschirm- und Schriftgröße um.', note: 'EPUB lässt den Leser die Schriftgröße ändern und den Text neu umbrechen — genau das macht lange Dokumente auf Handy und E-Reader erträglich.' },
    jpg: { about: 'JPG nutzt verlustbehaftete Kompression, die auf Fotos zugeschnitten ist: Sie wirft die Details weg, die das Auge am wenigsten bemerkt. Das macht Fotos klein, erzeugt aber weiche, blockige Artefakte an harten Kanten und an Text.', note: 'JPG liefert kleine Dateien, die sich buchstäblich überall öffnen lassen — um den Preis dauerhaft verworfener Details und fehlender Transparenz.' },
    jfif: { about: 'JFIF ist ein JPEG-Bild mit anderer Dateiendung; die Pixel darin sind gewöhnliche JPEG-Daten, doch Windows weigert sich oft, die Datei an die gewünschte App zu übergeben.', note: 'JFIF ist im Grunde nur JPEG unter anderem Namen.' },
    png: { about: 'PNG ist verlustfrei: Es speichert jedes Pixel exakt, unterstützt einen vollständigen Alphakanal für Transparenz und verschlechtert sich beim erneuten Speichern nie. Deshalb ist es das Format der Wahl für Screenshots, Logos und Oberflächengrafiken.', note: 'PNG bewahrt jedes Pixel genau so, wie es ist, und unterstützt echte Transparenz — es übersteht wiederholtes Bearbeiten ohne Qualitätsverlust.' },
    webp: { about: 'WebP ist Googles modernes Web-Bildformat; es komprimiert bei ähnlicher Qualität deutlich stärker als JPG oder PNG und beherrscht Transparenz und Animation, doch viele Desktop- und Druckprogramme können es noch immer nicht öffnen.', note: 'WebP erzeugt die kleinsten Dateien der gängigen Webformate und unterstützt Transparenz.' },
    bmp: { about: 'BMP speichert rohe, praktisch unkomprimierte Pixeldaten. Das ist perfekt originalgetreu und zugleich enorm verschwenderisch — ein Foto kann leicht zehnmal größer sein als dasselbe Bild als PNG.', note: 'BMP ist roh und unkomprimiert — genau das, was alte Windows-Software und manche Scanner erwarten.' },
    tiff: { about: 'TIFF ist das Archiv- und Druckvorstufenformat: verlustfrei, hohe Farbtiefe, mehrere Seiten oder Ebenen möglich — und entsprechend groß.', note: 'TIFF ist das Format, nach dem Druckereien und Archive fragen, weil nichts verworfen wird.' },
    gif: { about: 'GIF ist auf eine Palette von 256 Farben pro Einzelbild begrenzt, weshalb Fotos darin Streifen zeigen. Dafür animiert es und spielt fast überall im Internet direkt inline ab.', note: 'GIF animiert und spielt in Chat-Apps, Ticketsystemen und Foren direkt inline ab, ist aber auf 256 Farben pro Einzelbild begrenzt.' },
    ico: { about: 'ICO ist ein Windows-Symbolcontainer, der dieselbe Grafik in mehreren Größen zugleich enthält, damit das System 16×16 für einen Tab und 256×256 für eine Desktopverknüpfung wählen kann.', note: 'ICO bündelt mehrere Auflösungen in einer Datei — genau das, was Favicons und Windows-Programmsymbole brauchen.' },
