    wav: { about: 'WAV speichert Ton unkomprimiert, Sample für Sample, genau so wie aufgenommen — deshalb arbeiten Studios damit, und deshalb belegt eine Minute Stereo in CD-Qualität rund 10 MB.', note: 'WAV ist unkomprimiert und verlustfrei, sodass Schnitt- und Mastering-Programme es verarbeiten können, ohne vorher etwas dekodieren zu müssen.' },
    flac: { about: 'FLAC komprimiert Ton verlustfrei: Es ist etwa halb so groß wie WAV und dekodiert dennoch zu einer bitgenauen Kopie der Originalaufnahme zurück.', note: 'FLAC ist bitgenau, aber nur etwa halb so groß wie WAV.' },
    aac: { about: 'AAC ist der verlustbehaftete Codec hinter Apple Music, YouTube und den meisten Streamingdiensten; bei gleicher Bitrate klingt er in der Regel besser als MP3.', note: 'AAC klingt bei gleicher Bitrate besser als MP3 und ist der Standard in der Apple- und Streamingwelt.' },
    ogg: { about: 'OGG Vorbis ist ein patentfreier verlustbehafteter Codec, den Spiele, Open-Source-Software und Wikipedia bevorzugen — bei kleinerer Dateigröße mit MP3 vergleichbar.', note: 'OGG ist frei von Patentbeschränkungen, weshalb Spiele-Engines und Open-Source-Projekte es bevorzugen.' },
    m4a: { about: 'M4A ist ein MP4-Container, der nur Ton enthält, normalerweise AAC — das Format, das iTunes, Apple Music und iPhone-Sprachmemos erzeugen.', note: 'M4A ist die Standard-Audiodatei im Apple-Ökosystem.' },
    wma: { about: 'WMA ist Microsofts verlustbehafteter Audiocodec aus der Windows-Media-Player-Zeit, außerhalb von Windows kaum unterstützt und faktisch eingestellt.', note: 'WMA ist ein veralteter, nur unter Windows verbreiteter Audiocodec.' },
